SELECT ?sensor ?sensorClass WHERE {
  ?zone rdfs:label "Perimeter_top_ZN_4" .
  {
    ?sensor brick:isPointOf ?zone .
    ?sensor a brick:Electric_Power_Sensor .
  } UNION {
    ?sensor brick:isPointOf ?zone .
    ?sensor a brick:Occupancy_Sensor .
  }
  ?sensor ref:hasTimeseriesId ?tsid .
}

SELECT ?zone ?sensor ?sensorClass WHERE {
  ?zone a brick:Zone .
  ?sensor brick:isPointOf ?zone .
  { ?sensor a brick:Electric_Power_Sensor } UNION { ?sensor a brick:Occupancy_Sensor }
  OPTIONAL { ?zone rdfs:label ?label }
}

SELECT ?sensor ?sensorClass ?tsid WHERE {
  ?zone rdfs:label "Perimeter_top_ZN_4" .
  ?sensor brick:isPointOf ?zone .
  { ?sensor a brick:Electric_Power_Sensor } UNION { ?sensor a brick:Occupancy_Sensor }
  ?sensor ref:hasTimeseriesId ?tsid .
  ?sensor a ?sensorClass .
}

SELECT ?point ?tsid ?class WHERE {
  ?point ref:hasTimeseriesId ?tsid .
  ?point a ?class .
  ?point brick:isPointOf ?zone .
  ?zone rdfs:label "Perimeter_top_ZN_4" .
}

